files.agent-descriptor.json:
{
  "format": "agent-descriptor-v1",
  "agent_version": "1.0.0",
  "does": "Summarizes a document into a one-page brief, read aloud.",
  "offerings": [
    {
      "id": "summarize",
      "name": "Summarize a document",
      "inputs": [
        {
          "name": "document",
          "kind": "document",
          "required": true
        }
      ],
      "outputs": [
        {
          "name": "brief",
          "kind": "text/markdown",
          "when": "per_task"
        }
      ],
      "steps": [
        {
          "id": "fetch",
          "name": "Fetch the document"
        }
      ]
    }
  ],
  "refusals": "summarizing a document it could not read.\nadding a claim the document does not make.",
  "escalates": [
    "a document marked confidential."
  ],
  "records": [
    {
      "name": "the document as received",
      "when": "per_task",
      "file": "*/document"
    },
    {
      "name": "the brief as sent",
      "when": "per_task"
    }
  ],
  "systems": [
    {
      "name": "speech",
      "access": "trigger",
      "needs": "to read the brief aloud",
      "leaves": true
    },
    {
      "name": "documents",
      "access": "read",
      "needs": "to read the document"
    }
  ]
}

