{
  "format": "agent-install-v1",
  "runtimes": [
    {
      "name": "node",
      "version": ">=20"
    }
  ],
  "binaries": [],
  "dependencies": [
    {
      "skill": "fetch",
      "lockfile": "skills/fetch/scripts/package-lock.json",
      "sha256": "d5e0209440bfcfcf1af3422aaab2db36d6c41c4e455c1aec3cec9b652ef15aed"
    }
  ],
  "systems": [
    {
      "name": "speech",
      "kind": "service",
      "credential": "speech-key",
      "env": "SPEECH_TOKEN",
      "spends": {
        "unit": "characters"
      }
    },
    {
      "name": "documents",
      "kind": "directory"
    }
  ],
  "ceilings": [
    {
      "system": "speech",
      "per": "task",
      "enforced_by": "runtime"
    }
  ],
  "directories": [
    {
      "name": "records",
      "purpose": "every record the descriptor names"
    },
    {
      "name": "work",
      "purpose": "inputs and drafts in progress"
    }
  ]
}

